<?php
declare(strict_types=1);
// Initial HTML only: does not execute JS, emulate HTTP, or claim browser validation.
$file=$argv[1];$doc=new DOMDocument('1.0','UTF-8');$before=libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8">'.file_get_contents($file),LIBXML_NONET);libxml_clear_errors();libxml_use_internal_errors($before);$x=new DOMXPath($doc);
function attrs(DOMElement $node,array $keys):array{$out=[];foreach($keys as $key)if($node->hasAttribute($key))$out[$key]=$node->getAttribute($key);return $out;}
function txt(DOMNode $node):string{return trim(preg_replace('/\s+/u',' ',$node->textContent));}
function scope(DOMNode $node):string{for($n=$node;$n instanceof DOMElement;$n=$n->parentNode){foreach(['data-place-slug','data-experience-slug','data-business-id'] as $a)if($n->hasAttribute($a))return $a.':'.$n->getAttribute($a);if(in_array($n->tagName,['section','main','aside','header','footer'],true)&&($n->hasAttribute('id')||in_array($n->tagName,['header','footer','aside'],true)))return $n->getAttribute('id')?:$n->tagName;}return 'document';}
$out=['validation'=>'parsed-initial-HTML-only','title'=>($x->query('//title')->item(0)?->textContent??''),'language'=>$doc->documentElement?->getAttribute('lang')];
foreach(['headings'=>'//h1|//h2|//h3|//h4|//h5|//h6','sections'=>'//main|//section|//article|//aside|//nav|//details|//dialog','links'=>'//a[@href]','forms'=>'//form','buttons'=>'//button|//summary|//input[@type="submit"]','images'=>'//img','media'=>'//video|//audio|//source|//iframe|//object','assets'=>'//script[@src]|//link[@rel="stylesheet"]'] as $kind=>$query){$out[$kind]=[];foreach($x->query($query) as $node){$entry=['tag'=>$node->tagName,'scope'=>scope($node)]+attrs($node,['id','class','href','target','rel','aria-label','aria-labelledby','aria-describedby','title','name','type','action','method','enctype','src','srcset','sizes','alt','width','height','loading','draggable','data-place-slug','data-experience-slug','data-business-id']);if(in_array($kind,['links','headings','buttons'],true))$entry['text']=txt($node);if($kind==='forms'){$entry['controls']=[];foreach($x->query('.//input|.//select|.//textarea|.//button',$node) as $control){$entry['controls'][]=attrs($control,['id','name','type','required','disabled','min','max','minlength','maxlength','pattern','accept','multiple','autocomplete','aria-label','aria-describedby']);}}$out[$kind][]=$entry;}}
$out['textNodes']=[];foreach($x->query('//body//text()[not(ancestor::script) and not(ancestor::style) and not(ancestor::noscript)]') as $node){$text=txt($node);if($text!=='')$out['textNodes'][]=$text;}
echo json_encode($out,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
